#[test]
fn remote_annotated_tag_command_failure_is_a_vcs_error_not_absence() {
    let runner = FakeRunner {
        calls: Mutex::new(Vec::new()),
        response: Box::new(|args| {
            assert_eq!(args[0], "ls-remote");
            Ok(CommandOutput {
                exit_code: Some(128),
                stdout: String::new(),
                stderr: "fatal: unable to access remote".to_string(),
            })
        }),
    };
    let git = ShellGit::new(&runner, PathBuf::from("."));
    let name = TagName::parse("release-command-failure").unwrap();
    let target = CommitSha::parse(&"a".repeat(40)).unwrap();
    let digest = TagAnnotationDigest::from_annotation("Release command failure");

    let result = git.observe_remote_annotated_tag("origin", &name, &target, &digest);

    assert!(matches!(result, Err(VcsError::Git(message)) if message.contains("ls-remote")));
