+        let (_remote, local, head) = remote_fixture();
+        let runner = RealGitRunner;
+        let git = GitAccess::discover(local.path(), &runner);
+        let name = TagName::parse("release-push-readback").unwrap();
+        let annotation = "Release push readback";
+        let digest = TagAnnotationDigest::from_annotation(annotation);
+        run_git(
+            local.path(),
+            &[
+                "-c",
+                "tag.gpgSign=false",
+                "tag",
+                "-a",
+                "-m",
+                annotation,
+                name.as_str(),
+                head.as_str(),
+            ],
+        );
+
+        assert_eq!(
+            git.push_annotated_tag_and_confirm("origin", &name, &head, &digest, &permit())
+                .unwrap(),
+            RemoteAnnotatedTagObservation::Exact
+        );
+    }
+
+    #[test]
+    fn git_access_and_shell_create_push_and_observe_identical_annotation_bytes() {
+        let (_remote, local, head) = remote_fixture();
+        let runner = RealGitRunner;
+        let access = GitAccess::discover(local.path(), &runner);
+        let native_name = TagName::parse("release-native-roundtrip").unwrap();
+        let shell_name = TagName::parse("release-shell-roundtrip").unwrap();
+        // Deliberately include surplus terminators: the shared canonical
+        // serialization must make the native gix and shell paths identical.
+        let annotation = "Release canonical bytes\n\n";
+        let digest = TagAnnotationDigest::from_annotation(annotation);
+
+        access
+            .create_tag(
+                native_name.as_str(),
+                &head,
+                Some(annotation),
+                crate::TagSignPolicy::ForceUnsigned,
+                &permit(),
+            )
+            .unwrap();
+        assert_eq!(
+            access
+                .push_annotated_tag_and_confirm("origin", &native_name, &head, &digest, &permit())
+                .unwrap(),
+            RemoteAnnotatedTagObservation::Exact
+        );
+
+        let shell = ShellGit::new(&runner, local.path());
+        shell
+            .create_tag(
+                shell_name.as_str(),
+                &head,
+                Some(annotation),
+                crate::TagSignPolicy::ForceUnsigned,
+                &permit(),
+            )
+            .unwrap();
+        assert_eq!(
+            shell
+                .push_annotated_tag_and_confirm("origin", &shell_name, &head, &digest, &permit())
+                .unwrap(),
+            RemoteAnnotatedTagObservation::Exact
+        );
+    }
+
+    #[test]
+    fn remote_observation_ignores_local_replacement_refs_for_tag_objects() {
+        let (_remote, local, head) = remote_fixture();
